import type { Section } from "./types";

/**
 * Topic tags that mean the same thing, folded onto one canonical topic.
 *
 * The two banks name topics differently: Orthobullets tags follow the
 * Orthobullets page (`#acltear`), while Target Ortho tags follow its chapter
 * titles (`#acl`). Every Target Ortho question now sits under an Orthobullets
 * topic, so the scheduler lists exactly the 761 Orthobullets topics.
 *
 * The MCQ notes themselves were retagged, so in the current vault every entry
 * here is a no-op. The table exists so that a note still carrying an old
 * spelling, e.g. one restored from a backup, lands in the same topic. It holds
 * only the old tags whose questions all went to one topic. Broad chapters whose
 * questions were placed one by one across several topics (`#shoulderinstability`,
 * `#complicationsthr`, `#basicscience`, …) have no single target and are absent;
 * a note restored with one of those tags shows up as its own topic until retagged.
 *
 * Keys and values are lowercase bare tags. A value is never itself a key with a
 * different target, so one lookup is always enough.
 */
